def _validate_lsq_weights(w, npts):
    """Validate least-squares weights."""
    w = np.asarray(w, dtype=float)
    if w.ndim != 1 or w.shape[0] != npts:
        raise ValueError("`w` must be a 1D array with shape (npts,).")
    if np.any(w < 0):
        raise ValueError("`w` must contain only non-negative values.")
    if not np.isfinite(w).all():
        raise ValueError("`w` must contain only finite values.")
    if not np.any(w > 0):
        raise ValueError("At least one weight must be positive.")
    return w

def row_count(self) -> int:
        """Get the current number of rows."""
        return len(self.rows)

def is_pandas_df_or_series(X):
    """Return True if the X is a pandas dataframe or series.

    Parameters
    ----------
    X : {array-like, dataframe}
        The array-like or dataframe object to check.

    Returns
    -------
    bool
        True if the X is a pandas dataframe or series, False otherwise.
    """
    try:
        pd = sys.modules["pandas"]
    except KeyError:
        return False
    return isinstance(X, (pd.DataFrame, pd.Series))

def flatten_isinstance_classes(type_expr: TupleExpr) -> list[Expression]:
    """Flatten nested tuples in isinstance(obj, (A, (B, C))).

    isinstance() treats these the same as a flat tuple of classes.
    """
    result: list[Expression] = []
    for item in type_expr.items:
        if isinstance(item, TupleExpr):
            result.extend(flatten_isinstance_classes(item))
        else:
            result.append(item)
    return result

