def require_memory(nbytes, headroom=1.2):
    """Skip rather than get OOM-killed on machines that can't fit the benchmark.

    Pass the benchmark's own measured peak as `nbytes`; the headroom covers asv's
    own processes, which share the same cgroup as the benchmark on CI.
    """
    try:
        available = get_mem_info()["memavailable"]
    except Exception:
        # without psutil we can't tell; run it rather than skipping everywhere
        return
    needed = nbytes * headroom
    if needed > available:
        raise NotImplementedError(
            f"needs ~{needed / 1e9:.1f} GB, only {available / 1e9:.1f} GB available"
        )

def _count_consecutive_zeros(self, i):
        """
        Count the number of consecutive zeros in the i-th row of the table.

        """
        count = 0
        for expr in self[i, :]:
            if expr != 0:
                break
            count += 1

        return count

def generate_lorem_ipsum(
    n: int = 5, html: bool = True, min: int = 20, max: int = 100
) -> str:
    """Generate some lorem ipsum for the template."""
    from .constants import LOREM_IPSUM_WORDS

    words = LOREM_IPSUM_WORDS.split()
    result = []

    for _ in range(n):
        next_capitalized = True
        last_comma = last_fullstop = 0
        word = None
        last = None
        p = []

        # each paragraph contains out of 20 to 100 words.
        for idx, _ in enumerate(range(randrange(min, max))):
            while True:
                word = choice(words)
                if word != last:
                    last = word
                    break
            if next_capitalized:
                word = word.capitalize()
                next_capitalized = False
            # add commas
            if idx - randrange(3, 8) > last_comma:
                last_comma = idx
                last_fullstop += 2
                word += ","
            # add end of sentences
            if idx - randrange(10, 20) > last_fullstop:
                last_comma = last_fullstop = idx
                word += "."
                next_capitalized = True
            p.append(word)

        # ensure that the paragraph ends with a dot.
        p_str = " ".join(p)

        if p_str.endswith(","):
            p_str = p_str[:-1] + "."
        elif not p_str.endswith("."):
            p_str += "."

        result.append(p_str)

    if not html:
        return "\n\n".join(result)
    return markupsafe.Markup(
        "\n".join(f"<p>{markupsafe.escape(x)}</p>" for x in result)
    )

