def _dup_recurse_pow(f: dup[Er], exp: int, prec: int, K: Domain[Er]) -> dup[Er]:
    """
    Helper function for dup_series_pow.
    """
    if exp == 1:
        return dup_truncate(f, prec, K)

    q, r = divmod(exp, 2)
    half = _dup_recurse_pow(f, q, prec, K)
    square = dup_series_mul(half, half, prec, K)

    if r == 0:
        return square
    return dup_series_mul(square, f, prec, K)

def extract_capi(module):
    """
    Return a sorted dict {function_name: capsule_signature_string} for every
    entry in module.__pyx_capi__.

    Entries for which PyCapsule_GetName returns NULL (should never happen for
    Cython-generated capsules, but be defensive) are omitted with a warning.
    """
    result = {}
    for name, capsule in module.__pyx_capi__.items():
        raw = _get_name(capsule)
        if raw is None:
            print(f"WARNING: PyCapsule_GetName returned NULL for {name!r}",
                  file=sys.stderr)
            continue
        result[name] = raw.decode("utf-8")
    return dict(sorted(result.items()))

def _check_parameters(self, X, xp=None):
        """Check the Gaussian mixture parameters are well defined."""
        _, n_features = X.shape

        if self.weights_init is not None:
            self.weights_init = _check_weights(
                self.weights_init, self.n_components, xp=xp
            )

        if self.means_init is not None:
            self.means_init = _check_means(
                self.means_init, self.n_components, n_features, xp=xp
            )

        if self.precisions_init is not None:
            self.precisions_init = _check_precisions(
                self.precisions_init,
                self.covariance_type,
                self.n_components,
                n_features,
                xp=xp,
            )

        allowed_init_params = ["random", "random_from_data"]
        if (
            get_config()["array_api_dispatch"]
            and self.init_params not in allowed_init_params
        ):
            raise NotImplementedError(
                f"Allowed `init_params` are {allowed_init_params} if "
                f"'array_api_dispatch' is enabled. You passed "
                f"init_params={self.init_params!r}, which are not implemented to work "
                "with 'array_api_dispatch' enabled. Please disable "
                f"'array_api_dispatch' to use init_params={self.init_params!r}."
            )

def content_disposition_header(
    disptype: str,
    quote_fields: bool = True,
    _charset: str = "utf-8",
    params: dict[str, str] | None = None,
) -> str:
    """Sets ``Content-Disposition`` header for MIME.

    This is the MIME payload Content-Disposition header from RFC 2183
    and RFC 7579 section 4.2, not the HTTP Content-Disposition from
    RFC 6266.

    disptype is a disposition type: inline, attachment, form-data.
    Should be valid extension token (see RFC 2183)

    quote_fields performs value quoting to 7-bit MIME headers
    according to RFC 7578. Set to quote_fields to False if recipient
    can take 8-bit file names and field values.

    _charset specifies the charset to use when quote_fields is True.

    params is a dict with disposition params.
    """
    if not disptype or not (TOKEN > set(disptype)):
        raise ValueError(f"bad content disposition type {disptype!r}")

    value = disptype
    if params:
        lparams = []
        for key, val in params.items():
            if not key or not (TOKEN > set(key)):
                raise ValueError(f"bad content disposition parameter {key!r}={val!r}")
            if quote_fields:
                if key.lower() == "filename":
                    qval = quote(val, "", encoding=_charset)
                    lparams.append((key, '"%s"' % qval))
                else:
                    try:
                        qval = quoted_string(val)
                    except ValueError:
                        qval = "".join(
                            (_charset, "''", quote(val, "", encoding=_charset))
                        )
                        lparams.append((key + "*", qval))
                    else:
                        lparams.append((key, '"%s"' % qval))
            else:
                qval = val.replace("\\", "\\\\").replace('"', '\\"')
                lparams.append((key, '"%s"' % qval))
        sparams = "; ".join("=".join(pair) for pair in lparams)
        value = "; ".join((value, sparams))
    return value

def import_prefix(self, path: str) -> None:
        """Resolve all the modules in the registry that start with the
        specified path.
        """
        for module in self.module_registry:
            if self.prefix:
                key = module.split(self.prefix)[-1].replace(".", "_")
            else:
                key = module
            if (
                not path or module.startswith(path)
            ) and key not in self.__dict__:
                __import__(module, globals(), locals())
                self.__dict__[key] = globals()[key] = sys.modules[module]

